// C implementation of vstodo cmdDemo header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_demo.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_demo.go.\n\n#ifndef VSTODO_C_CMD_DEMO_H\n#define VSTODO_C_CMD_DEMO_H\n\n// Run a demonstration of vstodo functionality.\n// Equivalent to Go cmdDemo function.\n// app — vstodo application context pointer\n// args — demo command arguments\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_demo(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_DEMO_H